"use client";

import { useState } from "react";
import ScannerControls from "@/components/ScannerControls";
import ScanCard from "@/components/ScanCard";
import ResultsTable from "@/components/ResultsTable";

export default function Home() {
  const [results, setResults] = useState<any[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [lastScanTime, setLastScanTime] = useState<string | null>(null);

  const handleScan = async () => {
    console.log("Бутонът е натиснат, стартира скан...");
    setIsScanning(true);

    try {
      const res = await fetch("/api/scan");
      const data = await res.json();
      console.log("Данни от API:", data);

      if (data.results) {
        setResults(data.results);
        setLastScanTime(new Date().toLocaleTimeString());
      }
    } catch (error) {
      console.error("Грешка при сканиране:", error);
    } finally {
      setIsScanning(false);
    }
  };

  const highCount = results.filter((r) => r.conviction === "HIGH").length;
  const mediumCount = results.filter((r) => r.conviction === "MEDIUM").length;

  return (
    <main className="min-h-screen bg-slate-950 text-slate-100 p-6">
      <div className="max-w-7xl mx-auto space-y-6">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          <div className="lg:col-span-1">
            <ScannerControls
              onScan={handleScan}
              isScanning={isScanning}
              totalScanned={results.length}
              highCount={highCount}
              mediumCount={mediumCount}
              lastScanTime={lastScanTime}
            />
          </div>

          <div className="lg:col-span-3">
            {/* Cards View */}
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
              {results.slice(0, 6).map((r) => (
                <ScanCard key={r.symbol} result={r} />
              ))}
            </div>

            {/* Table View */}
            <div className="mt-8 bg-slate-900/40 border border-slate-800 rounded-xl p-4">
              <ResultsTable results={results} filter="ALL" />
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
